<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $order->reference }} Final Receipt</title><link rel="stylesheet" href="/print.css"></head><body>
@php($subtotal = $items->sum('amount_cents')) @php($taxable = max(0, $subtotal + $order->labour_cents + $order->commission_cents + $order->freight_cents + $order->other_charges_cents - $order->discount_cents)) @php($gst = $order->total_cents - $taxable)
<div class="print-actions"><button onclick="window.print()">Print / Save PDF</button><button onclick="window.close()">Close</button></div>
<main class="paper receipt-paper"><header class="receipt-header"><div><small>Voucher S.No</small><strong>{{ $order->reference }}</strong></div><h1>JSSC AZAD</h1><div><small>{{ $title }}</small><strong>{{ $order->goods_number ?: '—' }}</strong></div></header><section class="receipt-meta"><div><small>M/s.</small><strong>{{ $order->party_name }}</strong></div><div><small>Group</small><strong>{{ $order->group_head_name }}</strong></div><div><small>Dated</small><strong>{{ date('d-m-Y', strtotime($order->date)) }}</strong></div></section>
<table class="print-table receipt-table"><thead><tr><th>Sr</th><th>Description</th><th>Diff.</th><th>B. Rate</th><th>Qty.</th><th>Rate</th><th>Amount</th></tr></thead><tbody>@foreach($items as $item)<tr><td>{{ $loop->iteration }}</td><td>{{ $item->description }}</td><td class="num">{{ number_format($item->difference_cents/100, 2) }}</td><td class="num">{{ number_format($item->base_rate_cents/100, 2) }}</td><td class="num">{{ number_format($item->quantity, 3) }}</td><td class="num">{{ number_format($item->rate_cents/100, 2) }}</td><td class="num">{{ number_format($item->amount_cents/100, 2) }}</td></tr>@endforeach @for($i=$items->count();$i<12;$i++)<tr class="blank"><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td></tr>@endfor</tbody><tfoot><tr><th colspan="4">Total Quantity</th><th class="num">{{ number_format($items->sum('quantity'), 3) }}</th><th>Total</th><th class="num">{{ number_format($subtotal/100, 2) }}</th></tr></tfoot></table>
<section class="receipt-bottom"><div class="average"><strong>AVG. {{ $items->sum('quantity') > 0 ? number_format(($subtotal/100)/$items->sum('quantity'), 2) : '0.00' }}</strong><div class="charges"><span>Labour<br><b>{{ number_format($order->labour_cents/100, 2) }}</b></span><span>Discount<br><b>{{ number_format($order->discount_cents/100, 2) }}</b></span><span>Comm.<br><b>{{ number_format($order->commission_cents/100, 2) }}</b></span><span>Freight<br><b>{{ number_format($order->freight_cents/100, 2) }}</b></span><span>Others<br><b>{{ number_format($order->other_charges_cents/100, 2) }}</b></span></div></div><table class="totals-box"><tr><th>Taxable</th><td>{{ number_format($taxable/100, 2) }}</td></tr><tr><th>GST {{ number_format($order->gst_percent, 2) }}%</th><td>{{ number_format($gst/100, 2) }}</td></tr><tr class="grand"><th>G Total</th><td>{{ number_format($order->total_cents/100, 2) }}</td></tr></table></section><footer class="signature"><span>Prepared By</span><span>Checked By</span><span>Authorised Signatory</span></footer></main></body></html>
